import{_ as a,o as e,c as t,a1 as l}from"./chunks/framework.Ccs17H5l.js";const h=JSON.parse('{"title":"Simulator Usage Guide","description":"","frontmatter":{},"headers":[],"relativePath":"old-docs/SETUPS/Simulator.md","filePath":"old-docs/SETUPS/Simulator.md"}'),o={name:"old-docs/SETUPS/Simulator.md"};function i(n,s,r,p,u,c){return e(),t("div",null,[...s[0]||(s[0]=[l('<h1 id="simulator-usage-guide" tabindex="-1">Simulator Usage Guide <a class="header-anchor" href="#simulator-usage-guide" aria-label="Permalink to &quot;Simulator Usage Guide&quot;">​</a></h1><p>This guide explains how to use the official NumWorks simulator to test the execution of the test example.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="./Setup.html">Setup</a></li></ul><h2 id="launching-the-simulator" tabindex="-1">Launching the simulator <a class="header-anchor" href="#launching-the-simulator" aria-label="Permalink to &quot;Launching the simulator&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>You must use your OS terminal (not an IDE terminal)</p></div><p>Make sure you are inside the Docker container.</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">chmod</span><span style="color:#CE9178;"> +x</span><span style="color:#CE9178;"> ./shell.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">./shell.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Then start the simulator with the following command:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">just</span><span style="color:#CE9178;"> sim</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>On first use, the script will download the official NumWorks simulator and compile it. This can take a long time, so please be patient.</p><p>Add a number of CPU cores to the build process to speed it up :</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">just</span><span style="color:#CE9178;"> sim</span><span style="color:#B5CEA8;"> 8</span><span style="color:#6A9955;"> # replace 8 with the number of CPU cores you want to use</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></div><p>A window should open with the NumWorks calculator simulator. You can now test your application in the simulator.</p>',13)])])}const m=a(o,[["render",i]]);export{h as __pageData,m as default};
